func updateENR(...) error {
  enrForkID := &pb.ENRForkID{
    CurrentForkDigest: entry.ForkDigest[:],  // 4 bytes
    NextForkVersion:   next.ForkVersion[:],  // 4 bytes
    NextForkEpoch:     next.Epoch,           // 8 bytes
  }
  enc, err := enrForkID.MarshalSSZ()  // always 16 bytes (SSZ fixed-size)
  forkEntry := enr.WithEntry(eth2EnrKey, enc)
  node.Set(forkEntry)
}

func forkEntry(record *enr.Record) (*pb.ENRForkID, error) {
  sszEncodedForkEntry := make([]byte, 16)  // expects 16 bytes
  entry := enr.WithEntry(eth2EnrKey, &sszEncodedForkEntry)
  record.Load(entry)  // no explicit size validation
  forkEntry.UnmarshalSSZ(sszEncodedForkEntry)
}

func compareForkENR(self, peer *enr.Record) error {
  if !bytes.Equal(peerEntry.CurrentForkDigest, selfEntry.CurrentForkDigest) { return errCurrentDigestMismatch }
  if peerEntry.NextForkEpoch != selfEntry.NextForkEpoch {
    // Log trace, return nil -- peer accepted despite incompatible fork view!
    return nil
  }
  if !bytes.Equal(peerEntry.NextForkVersion, selfEntry.NextForkVersion) { return errNextVersionMismatch }
  if !params.FuluEnabled() { return nil }
  // FuluEnabled() check for nfd: TOCTOU window at fork activation
  if peerNFD != selfNFD { return errNextDigestMismatch }
}

func (s *Service) forkWatcher() {
  slotTicker := slots.NewSlotTicker(s.genesisTime, params.BeaconConfig().SecondsPerSlot)
  for {
    select {
    case currSlot := <-slotTicker.C():
      // Wall-clock epoch - NO sync state check
      currentEpoch := slots.ToEpoch(currSlot)
      newEntry := params.GetNetworkScheduleEntry(currentEpoch)
      if newEntry.ForkDigest != scheduleEntry.ForkDigest {
        updateENR(s.dv5Listener.LocalNode(), newEntry, nextEntry)
      }
    }
  }
}

func (dv *RODataColumnsVerifier) ValidProposerSignature(ctx context.Context) (err error) {
  for _, dataColumn := range dv.dataColumns {
    signatureData := columnToSignatureData(dataColumn)
    seen, err := dv.sc.SignatureVerified(signatureData)  // cache check
    if seen { continue }  // cache hit
    parentState, err := dv.parentState(ctx, dataColumn)
    if err = dv.sc.VerifySignature(signatureData, parentState); err != nil {
      return ErrInvalidProposerSignature
    }
  }
}

// Layer 1: ValidFields - VerifyDataColumnSidecar (basic struct)
// Layer 2: SidecarInclusionProven - VerifyDataColumnSidecarInclusionProof (Merkle)
// Layer 3: SidecarKzgProofVerified - batch KZG cell proof verification
// allSatisfied() requires all GossipDataColumnSidecarRequirements to be met

// Execution order in validateDataColumn:
// 1. ValidFields (cheap)
// 2. CorrectSubnet (cheap)
// 3. NotFromFutureSlot (cheap, IGNORE)
// 4. SlotAboveFinalized (medium, IGNORE)
// 5. SidecarParentSeen (cache, IGNORE)
// 6. SidecarParentValid (cache, REJECT)
// 7. ValidProposerSignature (BLS, EXPENSIVE, REJECT)
// 8. SidecarParentSlotLower (cheap)
// 9. SidecarDescendsFromFinalized (forkchoice)
// 10. SidecarInclusionProven (Merkle, medium)
// 11. validateWithKzgBatchVerifier (KZG, MOST EXPENSIVE)
// 12. hasSeenDataColumnIndex check (AFTER KZG!)
// 13. SidecarProposerExpected (shuffling, expensive)

func (dv *RODataColumnsVerifier) SidecarProposerExpected(ctx context.Context) (err error) {
  // Verify ProposerIndex against shuffling-derived expected proposer
  idx, cached := dv.pc.Proposer(checkpoint, dataColumnSlot)
  if !cached {
    idx, err = dv.pc.ComputeProposer(ctx, parentRoot, dataColumnSlot, parentState)
  }
  if idx != dataColumn.ProposerIndex() { return errSidecarUnexpectedProposer }
}
